// ===== Konfiguration: ein Eintrag pro Zoom-Webinar (Teil des Webinar-Themas) =====
// attended = teilgenommen, full = vollständig teilgenommen, notAttended = nicht teilgenommen
const WEBINARS = [
  { match: 'E-Mail Zustellung für Anfänger', attended: '13327964', full: '13440472', notAttended: '13445226' },
  { match: 'E-Mail Zustellung für Experten', attended: '13327965', full: '13445224', notAttended: '13445225' },
];
const FULL_ATTENDANCE_RATIO = 0.9; // above this share of the actual webinar length: fully attended
const MIN_ATTENDANCE_RATIO = 0;    // below this share: counted as not attended (0 = every join counts)
// ================================================================================

const ev = $('Listen to ending Zoom webinars').first().json.body.payload.object;
const cfg = WEBINARS.find(w => (ev.topic || '').includes(w.match));
if (!cfg) return []; // Webinar is not configured: nothing to do
for (const k of ['attended', 'full', 'notAttended']) {
  if (!/^\d+$/.test(String(cfg[k]))) throw new Error(`Tag-ID "${k}" für "${cfg.match}" ist nicht konfiguriert (Code-Knoten "Aggregate and classify").`);
}

// Actual webinar length in seconds; fallback: scheduled duration (minutes)
const start = new Date(ev.start_time).getTime();
const end = new Date(ev.end_time).getTime();
const actual = end > start ? Math.round((end - start) / 1000) : (Number(ev.duration) || 0) * 60;

// Absentees as reported by Zoom (registered, never joined); empty if the call failed
const absentees = $('Get past Zoom webinar absentees').all().flatMap(i => i.json.registrants || []);

// Participants: drop host/panelists flagged internal, merge rejoins per e-mail
const byEmail = {};
for (const page of $('Get past Zoom webinar participants').all()) {
  for (const p of (page.json.participants || [])) {
    if (p.internal_user) continue;
    const email = (p.user_email || '').trim().toLowerCase();
    if (!email) continue;
    if (!byEmail[email]) byEmail[email] = { user_email: email, name: (p.name || '').trim(), duration: 0 };
    byEmail[email].duration += Number(p.duration) || 0;
  }
}

const base = { topic: (ev.topic || '').trim(), webinar_id: String(ev.id || ''), webinar_duration_seconds: actual,
  tag_attended: cfg.attended, tag_full: cfg.full, tag_not_attended: cfg.notAttended };

const out = [];
const seen = new Set();
for (const p of Object.values(byEmail)) {
  const ratio = actual > 0 ? Math.min(p.duration / actual, 1) : 0;
  const attended = p.duration > 0 && ratio >= MIN_ATTENDANCE_RATIO;
  seen.add(p.user_email);
  out.push({ json: { ...base, ...p, status: attended ? 'attended' : 'not_attended', attendance_ratio: ratio,
    fully_attended: attended && ratio > FULL_ATTENDANCE_RATIO } });
}
for (const r of absentees) {
  const email = (r.email || '').trim().toLowerCase();
  if (!email || seen.has(email)) continue;
  seen.add(email);
  const name = [r.first_name, r.last_name].filter(Boolean).join(' ');
  out.push({ json: { ...base, user_email: email, name, duration: 0, status: 'not_attended', attendance_ratio: 0, fully_attended: false } });
}
return out;
